import { useState, type ReactNode } from "react";

export function DesktopWindowFrame({
  title,
  children,
  controls = ["close", "minimize", "zoom"] as const,
  initialActive = false,
}: {
  title: string;
  children: ReactNode;
  controls?: readonly ("close" | "minimize" | "zoom")[];
  initialActive?: boolean;
}) {
  const [active, setActive] = useState(initialActive);
  const [minimized, setMinimized] = useState(false);

  return (
    <section
      className="dwin"
      data-active={active}
      onPointerDownCapture={() => setActive(true)}
      onFocusCapture={() => setActive(true)}
    >
      <header className="dwin-bar">
        <div className="dwin-controls">
          {controls.map((control) => (
            <button
              key={control}
              type="button"
              aria-label={control}
              data-control={control}
              className="dwin-control"
              onClick={() => {
                if (control === "minimize") setMinimized((v) => !v);
                if (control === "close") setActive(false);
              }}
            />
          ))}
        </div>
        <h3 className="dwin-title">{title}</h3>
      </header>

      {minimized ? null : <div className="dwin-body">{children}</div>}
    </section>
  );
}

