.dwin {
  display: flex;
  flex-direction: column;
  min-width: 280px;
  border-radius: 10px;
  overflow: hidden;
  background: var(--surface-raised, #ffffff);
  border: 1px solid var(--line-subtle, #d4d4d8);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
  transition: box-shadow 0.15s ease;
}
.dwin[data-active="true"] {
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.24);
  border-color: var(--line-strong, #a1a1aa);
}
.dwin-bar {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 32px;
  padding: 0 10px;
  background: var(--surface-inset, #f4f4f5);
  border-bottom: 1px solid var(--line-subtle, #d4d4d8);
  user-select: none;
}
.dwin-controls {
  position: absolute;
  left: 10px;
  display: flex;
  gap: 6px;
}
.dwin-control {
  width: 11px;
  height: 11px;
  padding: 0;
  border-radius: 50%;
  border: 1px solid rgba(0, 0, 0, 0.14);
  background: #d4d4d8;
  cursor: pointer;
}
.dwin-control[data-control='close'] { background: #ff5f57; }
.dwin-control[data-control='minimize'] { background: #febc2e; }
.dwin-control[data-control='zoom'] { background: #28c840; }
.dwin-control:focus-visible {
  outline: 2px solid var(--accent, #6366f1);
  outline-offset: 2px;
}
.dwin-title {
  margin: 0;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-muted, #52525b);
}
.dwin-body {
  flex: 1;
  padding: 16px;
  overflow: auto;
  font-size: 13px;
  color: var(--text-strong, #18181b);
}
